{
  "technical_and_design_decisions": [
    "Use Spring Boot 1.1.x spring-boot-starter-security dependency added to the spring-xd-dirt module's pom.xml (as prescribed in U1).",
    "Control Basic Auth via the Spring Boot property 'server.basic.enabled' and set its default to false in application.yml to preserve backward compatibility.",
    "Read single-user security overrides from servers.yml using the existing Spring Boot/YAML configuration mechanism, keeping all customizations outside source code.",
    "Extend the existing XD Shell 'admin config' command with --username and --password CLI options, reusing the shell's existing argument-parsing infrastructure.",
    "Combine U4 (latest Spring Boot SNAPSHOT) and U5 (latest Spring Boot RELEASE) into a single dependency-upgrade activity, since the work is structurally identical; SNAPSHOT is for development, RELEASE for production-bound builds.",
    "Treat U6 strictly as a research spike: deliver a written assessment with options, phased breakdown, and proposed new user stories rather than implementation code.",
    "Build Docker images on a Ubuntu base image (compatible with Java 7, e.g., ubuntu:14.04) using OpenJDK 7 to satisfy U7 and U8.",
    "For U7, install Redis and RabbitMQ in the same image (as a single sandbox) and seed default configurations so a user can run it with a single 'docker run'.",
    "For U8, keep the image lean (XD JAR + Java 7 only) and add production hardening: non-root user, healthcheck, optimized JVM settings, configurable external endpoints, and exposed tunables for Redis/RabbitMQ connection settings.",
    "Reuse the Dockerfile from U7 as the starting point for U8 to avoid duplicating work; the production image is essentially U7 minus the in-container Redis/RabbitMQ plus hardening.",
    "Include unit tests within each coding activity (per-activity) and a dedicated integration testing pass to validate the auth flow end-to-end and Docker images."
  ],
  "assumptions": [
    "A workday equals 8 hours of focused, productive development time for a single developer.",
    "The developer is already familiar with the Spring XD codebase, Maven build, and module layout; no extended ramp-up is required.",
    "The Maven build system, CI hooks, and Spring XD module structure (xd-admin-server, xd-shell, spring-xd-dirt) are already in place and require no restructuring.",
    "A development environment with JDK 7/8, Maven, and Docker is pre-installed and ready to use.",
    "U4 and U5 are similar in nature (dependency version bump) and are estimated as a single combined activity.",
    "U6 is a time-boxed research spike; no production code is written and no integration testing is performed against it beyond a review of the resulting document.",
    "External dependencies (Spring Boot release, Docker base images, Redis/RabbitMQ packages) are publicly available with no access restrictions or licensing blockers.",
    "Testing effort (unit tests) is embedded in each implementation activity rather than tracked as a separate activity; only cross-feature integration testing is a separate activity.",
    "Documentation updates are limited to user-facing release notes and a short README update for the Docker images; full reference documentation is out of scope.",
    "The 'production-ready' Docker image (U8) does not include TLS termination, secret management, or cluster orchestration; those are deferred to follow-up stories.",
    "Default credentials in the sandbox image (U7) are acceptable and documented as such; no real secrets are baked in."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and design",
      "activity_description": "Read and analyze the user stories, explore the spring-xd-dirt, xd-admin-server, and xd-shell module structure, identify the integration points for security, Docker, and the REST API spike, and produce a short design note covering property names, config keys, and Docker base image choices."
    , "most_likely_effort": 1.5
    },
    {
      "activity_id": "A2",
      "activity_name": "Spring Boot dependency upgrade (SNAPSHOT and RELEASE)",
      "activity_description": "Update the spring-xd-dirt pom.xml to pull the latest Spring Boot SNAPSHOT (U4) and the latest Spring Boot RELEASE (U5), verify the build resolves, and adjust any breaking API changes that surface from the upgrade. Includes verifying that the new Spring Boot version still satisfies the XD runtime requirements."
    , "most_likely_effort": 1.0
    },
    {
      "activity_id": "A3",
      "activity_name": "Basic Auth integration (U1)",
      "activity_description": "Add the spring-boot-starter-security dependency to spring-xd-dirt, set the default value of 'server.basic.enabled' to false in application.yml, verify the HTTP Basic Auth challenge is presented when the property is set to true, and add unit/integration tests covering both enabled and disabled states."
    , "most_likely_effort": 1.5
    },
    {
      "activity_id": "A4",
      "activity_name": "Single-user security configuration via servers.yml (U2)",
      "activity_description": "Implement support for overriding the Basic Auth user name and password through the servers.yml file, wire the properties into Spring Security's in-memory user details service, and add tests covering valid, missing, and malformed configurations."
    , "most_likely_effort": 1.5
    },
    {
      "activity_id": "A5",
      "activity_name": "XD Shell admin config enhancement (U3)",
      "activity_description": "Add --username and --password options to the XD Shell 'admin config' command, persist the credentials in the shell's saved configuration, and ensure subsequent shell commands send the credentials when talking to a secured admin server. Add tests for argument parsing, credential persistence, and HTTP request signing."
    , "most_likely_effort": 1.0
    },
    {
      "activity_id": "A6",
      "activity_name": "Archive REST API spike (U6)",
      "activity_description": "Assess the customer requirement for a REST endpoint that pushes an archive of custom module definitions and configurations, brainstorm implementation options, socialize the design with the team, identify delivery phases, and produce a spike document with proposed follow-up stories. No production code is delivered."
    , "most_likely_effort": 2.0
    },
    {
      "activity_id": "A7",
      "activity_name": "Sandbox Docker image (U7)",
      "activity_description": "Author a Dockerfile based on Ubuntu, install Java 7, copy the full XD JAR, install and start Redis and RabbitMQ, expose the relevant ports, and provide a simple run script. Verify the image boots cleanly with 'docker run', that all three services come up, and that the XD admin UI is reachable from the host."
    , "most_likely_effort": 3.0
    },
    {
      "activity_id": "A8",
      "activity_name": "Production-ready Docker image (U8)",
      "activity_description": "Reuse the U7 base layer to create a leaner production image containing only Ubuntu, Java 7, and the full XD JAR. Add production hardening: run as a non-root user, add a HEALTHCHECK, tune JVM defaults, externalize configuration via environment variables, and document environment variables for connecting to external Redis and RabbitMQ instances. Verify image build, run, and that XD starts successfully against external services."
    , "most_likely_effort": 3.5
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration testing",
      "activity_description": "Execute end-to-end tests covering the full increment: Basic Auth enabled/disabled via property, servers.yml overrides, XD Shell passing credentials to a secured admin server, and both Docker images booting and serving traffic. Triage and fix any defects discovered."
    , "most_likely_effort": 1.5
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation",
      "activity_description": "Update the project README and release notes with the new security properties, XD Shell flags, and Docker image usage instructions. Document default credentials and security caveats for the sandbox image and note that the production image is intended as a baseline."
    , "most_likely_effort": 1.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 17.5
  }
}
